class ReconnectingWebSocket {
  constructor(url, opts = {}) {
    this.url = url;
    this.attempt = 0;
    this.maxDelay = opts.maxDelay || 30000;
    this.baseDelay = opts.baseDelay || 1000;
    this.connect();
  }
  getDelay() {
    const exp = Math.min(this.baseDelay * 2 ** this.attempt, this.maxDelay);
    return exp / 2 + Math.random() * exp / 2; // full jitter
  }
  connect() {
    this.ws = new WebSocket(this.url);
    this.ws.onclose = () => {
      const delay = this.getDelay();
      this.attempt++;
      setTimeout(() => this.connect(), delay);
    };
    this.ws.onopen = () => { this.attempt = 0; };
  }
}

const v8 = require('v8');
class LeakDetector extends EventEmitter {
  constructor(intervalMs = 30000, threshold = 50 * 1024 * 1024) {
    super();
    this.snapshots = [];
    this.threshold = threshold;
    this.timer = setInterval(() => this.check(), intervalMs);
  }
  check() {
    const mem = process.memoryUsage();
    this.snapshots.push({ ts: Date.now(), heapUsed: mem.heapUsed, rss: mem.rss });
    if (this.snapshots.length > 5) this.snapshots.shift();
    if (this.snapshots.length >= 3) {
      const growth = this.snapshots[this.snapshots.length-1].heapUsed - this.snapshots[0].heapUsed;
      if (growth > this.threshold) {
        this.emit('leak', { growth, snapshots: this.snapshots });
        v8.writeHeapSnapshot();
      }
    }
  }
}

import React, { memo, useMemo, useCallback } from 'react';
import { FixedSizeList as List } from 'react-window';

const ExpensiveRow = memo(({ item, onSelect }) => (
  <div onClick={() => onSelect(item.id)}>{item.name}</div>
), (prev, next) => prev.item.id === next.item.id);

function OptimizedList({ items, onFilter }) {
  const handleSelect = useCallback((id) => onFilter(id), [onFilter]);
  const sorted = useMemo(() => [...items].sort((a, b) => a.name.localeCompare(b.name)), [items]);
  return (
    <List height={600} itemCount={sorted.length} itemSize={50} width="100%">
      {({ index, style }) => (
        <ExpensiveRow key={sorted[index].id} item={sorted[index]} onSelect={handleSelect} style={style} />
      )}
    </List>
  );
}
